private static function reconciliation_scope( $id, $kind ) {
	return is_array( self::$reconciliation_scope ) && self::$reconciliation_scope['id'] === (int) $id && self::$reconciliation_scope['kind'] === $kind;
}

private static function warehouse_scanner_available() {
	if ( ! class_exists( 'TKD_Warehouse_Scanner' ) ) {
		return false;
	}
	foreach ( array( 'office_revision', 'begin_office_save', 'validate_office_change', 'end_office_save' ) as $method ) {
		if ( ! is_callable( array( 'TKD_Warehouse_Scanner', $method ) ) ) {
			return false;
		}
	}
	return true;
}

private static function status_audit( $id, $event, $from, $to ) {
	$rows = get_post_meta( $id, self::STATUS_AUDIT, true ); $rows = is_array( $rows ) ? $rows : array();
	$rows[] = array( 'event' => $event, 'from' => $from, 'to' => $to, 'at' => current_time( 'mysql' ), 'actor' => get_current_user_id(),
		'action' => isset( $_REQUEST['action'] ) && is_string( $_REQUEST['action'] ) ? sanitize_key( wp_unslash( $_REQUEST['action'] ) ) : '',
		'caller' => function_exists( 'wp_debug_backtrace_summary' ) ? substr( wp_debug_backtrace_summary( null, 0, true ), 0, 1800 ) : '' );
	update_post_meta( $id, self::STATUS_AUDIT, array_slice( $rows, -50 ) );
}

private static function was_posted( $id ) {
	return get_post_meta( $id, self::HANDOVER_POST_META, true ) !== ''
		|| get_post_meta( $id, '_tkd_fo_delivery_return_v1', true ) !== ''
		|| ! empty( get_post_meta( $id, '_tkd_fo_delivery_stock_journal', true ) );
}

public static function rework_guard( $id ) {
	$order = absint( get_post_meta( $id, '_tkd_fo_delivery_order_id', true ) );
	if ( ! current_user_can( 'manage_tkd_felicity' ) || ! current_user_can( 'edit_post', $id ) || ! $order || get_post_type( $id ) !== 'tkd_delivery' ) { return new WP_Error( 'rework', 'Немає доступу до видаткової.' ); }
	$historical = self::historical_stock_guard( $id ); if ( is_wp_error( $historical ) ) { return $historical; }
	if ( self::reconciliation_scope( $id, 'return_received' ) ) { return true; }
	$return = get_post_meta( $id, '_tkd_fo_delivery_return_v1', true );
	if ( $return !== '' && ( ! is_array( $return ) || ( $return['version'] ?? null ) !== 1 || ( $return['state'] ?? '' ) !== 'committed' ) ) { return new WP_Error( 'rework', 'Попереднє повернення не завершене. Повтор заблоковано до звірки складу.' ); }
	foreach ( array( '_tkd_fo_dispatch_v1', '_tkd_np_dispatch_v1' ) as $key ) {
		$r = get_post_meta( $id, $key, true );
		if ( $r === '' ) { continue; }
		if ( ! is_array( $r ) || ( $r['version'] ?? null ) !== 1 || ! in_array( $r['state'] ?? '', array( 'preparing', 'awaiting_handover' ), true ) ) { return new WP_Error( 'rework', 'Передача вже підтверджена або має невизначений стан. Потрібне окреме повернення, не перероблення.' ); }
		if ( ( $r['order'] ?? null ) !== $order || ! empty( $r['send_unknown'] ) || ! empty( $r['send_intent'] ) || in_array( $r['challenge']['state'] ?? '', array( 'pending', 'unknown' ), true ) ) { return new WP_Error( 'rework', 'Невідповідність замовлення або незавершена SMS-операція: спочатку звірте її результат.' ); }
	}
	// A live waybill needs carrier-side reconciliation; never silently detach it.
	if ( get_post_meta( $order, '_tkd_np_document_number', true ) !== '' ) { return new WP_Error( 'rework', 'Є ЕН Нової пошти. Спочатку потрібна звірка або скасування ЕН; ця дія її не скасовує.' ); }
	if ( get_post_meta( $order, '_pml_cashalot_receipt', true ) !== '' || get_post_meta( $order, '_pml_cashalot_return', true ) !== '' ) { return new WP_Error( 'rework', 'Є фіскальний чек або повернення. Спочатку потрібна окрема фіскальна звірка.' ); }
	if ( ! is_callable( array( 'PML_Release_Receipt', 'bank_clear' ) ) || PML_Release_Receipt::bank_clear( $order, '' ) !== true ) { return new WP_Error( 'rework', 'Відсутність незавершеного фіскального запиту не підтверджена.' ); }
	$status = get_post_meta( $id, '_tkd_fo_delivery_status', true );
	if ( ! in_array( $status, array( 'draft', 'issued', 'cancelled' ), true ) ) { return new WP_Error( 'rework', 'Невідомий статус видаткової.' ); }
	$journal = get_post_meta( $id, '_tkd_fo_delivery_stock_journal', true );
	if ( $status !== 'issued' && $journal !== '' && $journal !== array() ) { return new WP_Error( 'rework', 'Статус не відповідає журналу списання. Повторне повернення заборонено до звірки.' ); }
	return true;
}

public static function save_delivery( $post_id, $post, $update ) {
	if ( self::$saving || wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) ) {
		return;
	}
	if ( ! isset( $_POST['tkd_fo_delivery_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['tkd_fo_delivery_nonce'] ) ), 'tkd_fo_save_delivery' ) ) {
		return;
	}
	if ( ! current_user_can( 'manage_tkd_felicity' ) ) {
		return;
	}

	$scanner_active = class_exists( 'TKD_Warehouse_Scanner' );
	$scanner_lease = null;
	if ( $scanner_active ) {
		if ( ! self::warehouse_scanner_available() ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', 'Модуль складського сканування потребує оновлення. Видаткову не змінено.' );
			return;
		}
		$revision = isset( $_POST['tkd_ws_office_revision'] ) && is_string( $_POST['tkd_ws_office_revision'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_ws_office_revision'] ) ) : '';
		$scanner_lease = TKD_Warehouse_Scanner::begin_office_save( $post_id, $revision );
		if ( is_wp_error( $scanner_lease ) ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', $scanner_lease->get_error_message() );
			return;
		}
	}
	try {
		self::save_delivery_locked( $post_id, $post, $update );
	} finally {
		self::$saving = false;
		if ( $scanner_active ) {
			TKD_Warehouse_Scanner::end_office_save( $post_id, $scanner_lease );
		}
	}
}

private static function historical_stock_guard( $delivery_id ) {
	if ( metadata_exists( 'post', (int)$delivery_id, self::RECONCILIATION ) && ! self::reconciliation_scope( $delivery_id, 'already_shipped' ) && ! self::reconciliation_scope( $delivery_id, 'return_received' ) ) { return self::handover_post_error( 'Є окремий журнал складської звірки. Редагування, повторне проведення та повернення заблоковані; відкрийте результат звірки.' ); }
	if ( metadata_exists( 'post', (int) $delivery_id, '_tkd_fo_historical_stock_reconciliation_v1' ) ) {
		return self::handover_post_error( 'Історичне відвантаження звірено окремою складською операцією. Повторне проведення, редагування та звичайне скасування заблоковані. Для повернення потрібна окрема перевірка фактичного повернення товару.' );
	}
	if ( is_callable( array( 'TKD_FO_Legacy_Shipments', 'requires_reconciliation' ) ) && ! self::reconciliation_scope( $delivery_id, 'already_shipped' ) && ! self::reconciliation_scope( $delivery_id, 'return_received' ) && TKD_FO_Legacy_Shipments::requires_reconciliation( $delivery_id ) ) { return self::handover_post_error( 'У журналі цього замовлення вже є історичне списання. Повторне проведення або повернення через стару чернетку заборонено. Для повернення товару потрібна окрема складська звірка.' ); }
	return true;
}

public static function fiscal_guard( $delivery_id ) {
	if ( ! is_callable( array( 'TKD_Sales_Fiscal_Gate', 'check_delivery' ) ) ) { return self::handover_post_error( 'Фіскальна перевірка недоступна. Нове проведення заблоковано до відновлення модуля.' ); }
	try { $result = TKD_Sales_Fiscal_Gate::check_delivery( (int) $delivery_id ); }
	catch ( Throwable $error ) { return self::handover_post_error( 'Фіскальну перевірку не завершено. Нове проведення заблоковано.' ); }
	return $result === true ? true : ( is_wp_error( $result ) ? $result : self::handover_post_error( 'Немає однозначного підтвердження фіскальної готовності.' ) );
}

private static function save_delivery_locked( $post_id, $post, $update ) {
	$historical = self::historical_stock_guard( $post_id ); if ( is_wp_error( $historical ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $historical->get_error_message() ); return; }
	$handover_intent = get_post_meta( $post_id, self::HANDOVER_POST_META, true );
	if ( $handover_intent !== '' && ( ! is_array( $handover_intent ) || ( $handover_intent['version'] ?? null ) !== 1 || ( $handover_intent['state'] ?? '' ) !== 'committed' ) ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', 'Незавершена спроба проведення для передачі. Ручне збереження заблоковано, щоб не повторити списання; потрібна окрема звірка.' ); return;
	}
	$invoice_id = absint( get_post_meta( $post_id, '_tkd_fo_delivery_invoice_id', true ) );
	$previous_status = (string) get_post_meta( $post_id, '_tkd_fo_delivery_status', true );
	$previous_status = array_key_exists( $previous_status, self::status_labels() ) ? $previous_status : 'draft';
	$old_items  = get_post_meta( $post_id, '_tkd_fo_delivery_items', true );
	$old_items  = is_array( $old_items ) ? $old_items : array();
	$status     = isset( $_POST['tkd_fo_delivery_status'] ) && is_string( $_POST['tkd_fo_delivery_status'] ) ? sanitize_key( wp_unslash( $_POST['tkd_fo_delivery_status'] ) ) : $previous_status;
	$status     = array_key_exists( $status, self::status_labels() ) ? $status : $previous_status;
	$rework = ( $_POST['tkd_fo_delivery_command'] ?? '' ) === 'rework_delivery';
	$cancel = $rework || ( $_POST['tkd_fo_delivery_command'] ?? '' ) === 'cancel_delivery';
	if ( $rework && ( $_POST['tkd_fo_rework_on_site'] ?? '' ) !== '1' ) { TKD_FO_Inventory_Admin::set_notice( 'error', 'Підтвердьте, що всі товари ще на складі. Видаткову не змінено.' ); return; }
	if ( $cancel && ( $rework || self::was_posted( $post_id ) ) ) {
		$guard = self::rework_guard( $post_id );
		if ( is_wp_error( $guard ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $guard->get_error_message() ); return; }
	}
	if ( ! $cancel && self::was_posted( $post_id ) && $previous_status !== 'issued' ) { TKD_FO_Inventory_Admin::set_notice( 'error', 'Попереднє проведення збережено в історії. Для нової партії використайте «Переробити відвантаження» та нову видаткову, а не повторне проведення старої.' ); return; }
	if ( $cancel ) { $status = 'cancelled'; }
	if ( $status === 'cancelled' && $previous_status !== 'cancelled' && ! $cancel ) {
		self::status_audit( $post_id, 'blocked_implicit_cancel', $previous_status, $status );
		TKD_FO_Inventory_Admin::set_notice( 'warning', 'Видаткову не скасовано. Звичайне «Оновити» не скасовує документ; для цього є окрема кнопка «Скасувати видаткову».' ); return;
	}
	if ( $previous_status !== 'issued' && $status === 'issued' ) {
		$fiscal = self::fiscal_guard( $post_id ); if ( is_wp_error( $fiscal ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $fiscal->get_error_message() ); return; }
		// The fiscal gate verifies saved goods, never an unsaved form candidate.
		// Reject before number allocation or any broad form write; save a draft first.
		try {
			$candidate = self::sanitize_items( $invoice_id, $post_id, isset( $_POST['tkd_fo_delivery_items'] ) ? wp_unslash( $_POST['tkd_fo_delivery_items'] ) : array() );
			$unchanged = empty( $candidate['error'] ) && ! empty( $candidate['items'] ) && $candidate['items'] === $old_items;
		} catch ( Throwable $e ) { $unchanged = false; }
		if ( ! $unchanged ) { TKD_FO_Inventory_Admin::set_notice( 'error', 'Склад товарів відрізняється від збереженої видаткової. Спочатку збережіть чернетку, потім повторіть перевірку чека та проведення.' ); return; }
	}
	$resolved = self::delivery_items_for_display( $post_id );
	if ( $resolved['error'] && 'cancelled' !== $status ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', $resolved['error'] );
		return;
	}
	$date       = isset( $_POST['tkd_fo_delivery_date'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_fo_delivery_date'] ) ) : wp_date( 'Y-m-d' );
	$number     = isset( $_POST['tkd_fo_delivery_number'] ) ? sanitize_text_field( wp_unslash( $_POST['tkd_fo_delivery_number'] ) ) : '';
	$seller_status = 'issued' === $previous_status ? 'issued' : ( 'cancelled' === $status ? 'cancelled' : 'draft' );
	$seller     = self::seller_key_for_delivery( $post_id, $seller_status );
	$error      = '';

	// A seller change can carry a draft number into another seller's sequence.
	// Repair only a saved draft's unchanged conflicting number, never an explicit
	// replacement supplied by the manager or any issued/cancelled document.
	$renumbered_from = '';
	if ( 'issued' !== $previous_status ) {
		$saved_number = trim( (string) get_post_meta( $post_id, '_tkd_fo_delivery_number', true ) );
		$duplicate = $number !== '' && self::number_exists( $seller, $number, $post_id );
		$repair_draft = 'draft' === $previous_status && 'draft' === $status && $duplicate && $number === $saved_number;
		if ( $duplicate && ! $repair_draft ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', 'Цей номер уже зайнятий у продавця. Документ не змінено. Збережіть чернетку з її попереднім номером або залиште номер порожнім для автоматичної нумерації.' ); return;
		}
		if ( ! $number || $repair_draft ) {
			$renumbered_from = $repair_draft ? $number : '';
			$number = self::next_number( $seller, $date );
			if ( ! $number || self::number_exists( $seller, $number, $post_id ) ) {
				TKD_FO_Inventory_Admin::set_notice( 'error', 'Не вдалося призначити вільний номер. Документ не змінено; повторіть збереження чернетки.' ); return;
			}
		}
	}

	if ( 'issued' === $previous_status ) {
		$items = $old_items;
		$number = (string) get_post_meta( $post_id, '_tkd_fo_delivery_number', true );
		$date   = (string) get_post_meta( $post_id, '_tkd_fo_delivery_date', true );
		if ( 'cancelled' === $status ) {
			$stock_result = self::reverse_issued_delivery( $post_id );
			if ( is_wp_error( $stock_result ) ) {
				$error  = $error ? $error : $stock_result->get_error_message();
				$status = 'issued';
			}
		} elseif ( 'issued' !== $status ) {
			$error  = $error ? $error : 'Проведену видаткову можна лише скасувати з поверненням товару на склад.';
			$status = 'issued';
		}
	} elseif ( 'cancelled' === $status ) {
		// Cancelling an unissued note releases its allocation without remapping lines.
		$items = $old_items;
	} else {
		$raw_items = isset( $_POST['tkd_fo_delivery_items'] ) ? wp_unslash( $_POST['tkd_fo_delivery_items'] ) : array();
		$result    = self::sanitize_items( $invoice_id, $post_id, $raw_items );
		if ( ! empty( $result['source_mismatch'] ) ) {
			TKD_FO_Inventory_Admin::set_notice( 'error', $result['error'] );
			return;
		}
		$items     = $result['items'];
		if ( $result['error'] ) {
			$error  = $error ? $error : $result['error'];
			$status = 'draft';
		}
		if ( ! $items ) {
			$items  = $old_items;
			$error  = $error ? $error : 'Вкажіть кількість хоча б для однієї позиції.';
			$status = 'draft';
		}
		if ( self::warehouse_scanner_available() ) {
			$scanner_check = TKD_Warehouse_Scanner::validate_office_change( $post_id, $items, $status );
			if ( is_wp_error( $scanner_check ) ) {
				TKD_FO_Inventory_Admin::set_notice( 'error', $scanner_check->get_error_message() );
				return;
			}
		}
		if ( ! $error && 'issued' === $status ) {
			$stock_result = self::issue_delivery( $post_id, $items );
			if ( is_wp_error( $stock_result ) ) {
				$error  = $stock_result->get_error_message();
				$status = $previous_status;
			}
		}
	}

	if ( 'cancelled' === $previous_status && $error ) {
		// A failed reopen must leave the cancelled document's snapshot intact.
		TKD_FO_Inventory_Admin::set_notice( 'error', $error );
		return;
	}

	update_post_meta( $post_id, '_tkd_fo_delivery_number', $number );
	update_post_meta( $post_id, '_tkd_fo_delivery_date', $date );
	self::$cancel_scope = $cancel ? (int) $post_id : 0;
	try { update_post_meta( $post_id, '_tkd_fo_delivery_status', $status ); }
	finally { self::$cancel_scope = 0; }
	if ( get_post_meta( $post_id, '_tkd_fo_delivery_status', true ) !== $status ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', 'Не підтверджено збереження статусу видаткової. Не повторюйте складську дію; перевірте журнал.' ); return;
	}
	if ( ! $error && $previous_status !== $status ) { self::status_audit( $post_id, $cancel ? 'manager_cancel' : 'manager_save', $previous_status, $status ); }
	update_post_meta( $post_id, '_tkd_fo_delivery_seller_key', $seller );
	update_post_meta( $post_id, '_tkd_fo_delivery_items', $items );
	foreach ( array( 'place', 'receiver', 'payer', 'contract', 'application' ) as $field ) {
		if ( 'issued' === $previous_status ) {
			continue;
		}
		$value = isset( $_POST[ 'tkd_fo_delivery_' . $field ] ) ? sanitize_text_field( wp_unslash( $_POST[ 'tkd_fo_delivery_' . $field ] ) ) : '';
		update_post_meta( $post_id, '_tkd_fo_delivery_' . $field, $value );
	}

	if ( ! $error && $status === 'cancelled' && is_callable( array( 'TKD_Warehouse_Scanner', 'archive_cancelled_task' ) ) ) {
		$task_archive = TKD_Warehouse_Scanner::archive_cancelled_task( $post_id );
		if ( is_wp_error( $task_archive ) ) { TKD_FO_Inventory_Admin::set_notice( 'error', $task_archive->get_error_message() ); return; }
	}
	if ( ! $error && $previous_status !== $status && ( 'issued' === $status || ( 'issued' === $previous_status && 'cancelled' === $status ) ) && function_exists( 'do_action' ) ) {
		// Notification only: existing financial/stock processing and final metadata are already committed.
		do_action( 'tkd_fo_delivery_status_committed', $post_id, $previous_status, $status, $items );
	}
	if ( $error ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', $error );
	} else {
		$message = 'issued' === $status ? 'Видаткову проведено: товар списано зі складу по фактичних позиціях.' : ( 'cancelled' === $status && 'issued' === $previous_status ? 'Видаткову скасовано: товар повернуто на склад, резерв відновлено.' : 'Видаткову накладну збережено.' );
		if ( $renumbered_from ) { $message .= ' Номер ' . $renumbered_from . ' уже зайнятий у цього продавця; чернетці присвоєно № ' . $number . '.'; }
		TKD_FO_Inventory_Admin::set_notice( 'success', $message );
	}

	self::$saving = true;
	wp_update_post(
		array(
			'ID'          => $post_id,
			'post_title'  => $number ? 'Видаткова накладна ' . $number : 'Чернетка видаткової #' . $post_id,
			'post_status' => 'publish',
		)
	);
	self::$saving = false;
	if ( ! $error && isset( $_POST['post_ID'] ) && absint( $_POST['post_ID'] ) === (int) $post_id ) {
		$order_id = absint( get_post_meta( $post_id, '_tkd_fo_delivery_order_id', true ) );
		if ( ! $order_id && $invoice_id ) {
			$order_id = absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
		}
		TKD_FO_Orders::claim_responsibility( $order_id, 'Збережено видаткову № ' . $number );
	}
}

private static function issue_delivery( $delivery_id, $items ) {
	$historical = self::historical_stock_guard( $delivery_id ); if ( is_wp_error( $historical ) ) { return $historical; }
	$saved_items = get_post_meta( $delivery_id, '_tkd_fo_delivery_items', true );
	if ( ! is_array( $saved_items ) || ! $saved_items || $items !== $saved_items ) { return self::handover_post_error( 'Незбережені зміни товарів не можна провести за перевіркою чека для іншого складу. Спочатку збережіть чернетку.' ); }
	$fiscal = self::fiscal_guard( $delivery_id ); if ( is_wp_error( $fiscal ) ) { return $fiscal; }
	$handover_intent = get_post_meta( $delivery_id, self::HANDOVER_POST_META, true );
	if ( $handover_intent !== '' && ( ! is_array( $handover_intent ) || ( $handover_intent['state'] ?? '' ) !== 'pending' || ( self::$handover_post_scope['delivery'] ?? null ) !== (int) $delivery_id || ( self::$handover_post_scope['token'] ?? null ) !== ( $handover_intent['token'] ?? null ) ) ) { return self::handover_post_error( 'Повторне проведення видаткової з audit intent заборонено.' ); }
	$existing = get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true );
	if ( is_array( $existing ) && $existing ) {
		return true;
	}

	$order_id  = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_order_id', true ) );
	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$number    = trim( (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_number', true ) );
	$waybill_guard = self::validate_waybill_before_issue( $order_id );
	if ( is_wp_error( $waybill_guard ) ) {
		return $waybill_guard;
	}
	$reserved  = self::order_reservation_map( $order_id );
	$plan      = array();

	foreach ( $items as $line ) {
		$sku = isset( $line['sku'] ) ? trim( (string) $line['sku'] ) : '';
		$qty = TKD_FO_DB::decimal( isset( $line['quantity'] ) ? $line['quantity'] : 0, 3 );
		$item = $sku ? TKD_FO_DB::get_item_by_sku( $sku ) : null;
		if ( ! $item || $qty <= 0 ) {
			return new WP_Error( 'tkd_fo_delivery_stock_match', 'Не знайдено складську позицію для «' . ( isset( $line['name'] ) ? $line['name'] : $sku ) . '».' );
		}
		$item_id = (int) $item->id;
		if ( ! isset( $plan[ $item_id ] ) ) {
			$plan[ $item_id ] = array( 'item_id' => $item_id, 'sku' => $item->sku, 'quantity' => 0, 'reserved_released' => 0 );
		}
		$plan[ $item_id ]['quantity'] = round( $plan[ $item_id ]['quantity'] + $qty, 3 );
	}

	foreach ( $plan as &$entry ) {
		$item = TKD_FO_DB::get_item( $entry['item_id'] );
		$entry['reserved_released'] = min( $entry['quantity'], isset( $reserved[ $entry['item_id'] ] ) ? $reserved[ $entry['item_id'] ] : 0 );
		if ( ! $item || (float) $item->on_hand + 0.0001 < $entry['quantity'] ) {
			return new WP_Error( 'tkd_fo_delivery_shortage', 'Не вистачає фізичного залишку для ' . $entry['sku'] . '. Спочатку проведіть надходження на склад.' );
		}
		if ( (float) $item->reserved + 0.0001 < $entry['reserved_released'] ) {
			return new WP_Error( 'tkd_fo_delivery_reservation_mismatch', 'Резерв для ' . $entry['sku'] . ' не збігається зі складом. Перевірте замовлення перед відвантаженням.' );
		}
	}
	unset( $entry );

	$processed = array();
	foreach ( $plan as $entry ) {
		$result = TKD_FO_DB::change_stock(
			$entry['item_id'],
			array( 'on_hand' => -$entry['quantity'], 'reserved' => -$entry['reserved_released'] ),
			array(
				'type'       => 'delivery_ship',
				'order_id'   => $order_id,
				'invoice_id' => $invoice_id,
				'note'       => 'Видаткова № ' . $number . ' (часткове або повне відвантаження)',
			)
		);
		if ( is_wp_error( $result ) ) {
			self::rollback_stock_changes( $processed, $order_id, $invoice_id, $number );
			return $result;
		}
		$processed[] = $entry;
	}

	self::reduce_order_reservation( $order_id, $processed );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', array_values( $processed ) );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_stock_processed_at', current_time( 'mysql' ) );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_previous_order_status', get_post_meta( $order_id, '_tkd_status', true ) );
	if ( ! get_post_meta( $order_id, '_tkd_fo_status_before_partial_delivery', true ) ) {
		update_post_meta( $order_id, '_tkd_fo_status_before_partial_delivery', get_post_meta( $order_id, '_tkd_status', true ) );
	}
	self::refresh_order_fulfillment( $order_id, $invoice_id );
	return true;
}

public static function validate_waybill_before_issue( $order_id ) {
	$order_id = absint( $order_id );
	if ( ! $order_id ) {
		return new WP_Error( 'tkd_fo_delivery_order_missing', 'Видаткову не прив’язано до замовлення.' );
	}
	$delivery_method = sanitize_key( (string) get_post_meta( $order_id, '_tkd_np_delivery_method', true ) );
	if ( 'pickup' === $delivery_method ) {
		return true;
	}
	$waybill = trim( (string) get_post_meta( $order_id, '_tkd_np_document_number', true ) );
	if ( ! preg_match( '/^\d{12,20}$/D', $waybill ) ) {
		return new WP_Error( 'tkd_fo_delivery_waybill_required', 'Перед проведенням видаткової внесіть і збережіть ЕН Нової пошти (12–20 цифр) у картці замовлення.' );
	}
	return true;
}

private static function reverse_issued_delivery( $delivery_id ) {
	$guard = self::rework_guard( $delivery_id ); if ( is_wp_error( $guard ) ) { return $guard; }
	$key = '_tkd_fo_delivery_return_v1';
	$old = get_post_meta( $delivery_id, $key, true );
	if ( $old !== '' ) {
		if ( is_array( $old ) && ( $old['version'] ?? null ) === 1 && ( $old['state'] ?? '' ) === 'committed' && get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true ) === '' ) { return true; }
		return new WP_Error( 'rework', 'Попереднє повернення має невизначений результат. Повторне поповнення складу заблоковано до звірки.' );
	}
	$journal = get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true );
	if ( ! is_array( $journal ) || ! $journal ) { return new WP_Error( 'rework', 'Немає журналу списання для безпечного повернення.' ); }
	$order = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_order_id', true ) );
	$order_status = (string) get_post_meta( $order, '_tkd_status', true );
	$previous = (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_previous_order_status', true );
	$target = $order_status === 'shipped' && $previous ? $previous : $order_status;
	$restore = in_array( $target, array( 'payment_pending', 'cod_pending', 'invoice_pending', 'prepayment_invoice_sent', 'partially_paid', 'balance_pending', 'paid', 'deferred_payment' ), true );
	if ( self::reconciliation_scope( $delivery_id, 'return_received' ) ) { $restore = false; }
	$targets = array();
	foreach ( $journal as $entry ) {
		$item_id = absint( $entry['item_id'] ?? 0 ); $qty = (float) ( $entry['quantity'] ?? 0 ); $reserved = (float) ( $entry['reserved_released'] ?? 0 );
		$item = $item_id ? TKD_FO_DB::get_item( $item_id ) : null;
		if ( ! $item || ! is_finite( $qty ) || $qty <= 0 || ! is_finite( $reserved ) || $reserved < 0 || $reserved > $qty ) { return new WP_Error( 'rework', 'Пошкоджено журнал списання. Потрібна звірка; склад не змінено.' ); }
		if ( ! isset( $targets[ $item_id ] ) ) { $targets[ $item_id ] = array( 'on_hand' => (float) $item->on_hand, 'reserved' => (float) $item->reserved ); }
		$targets[ $item_id ]['on_hand'] += $qty;
		$targets[ $item_id ]['reserved'] += $restore ? $reserved : 0;
	}
	$intent = array( 'version' => 1, 'state' => 'pending', 'actor' => get_current_user_id(), 'at' => current_time( 'mysql' ), 'journal' => $journal, 'stock_targets' => $targets );
	if ( ! add_post_meta( $delivery_id, $key, wp_slash( $intent ), true ) ) { return new WP_Error( 'rework', 'Не вдалося зафіксувати початок повернення. Склад не змінено.' ); }
	wp_cache_delete( $delivery_id, 'post_meta' );
	if ( get_post_meta( $delivery_id, $key, true ) !== $intent ) { return new WP_Error( 'rework', 'Запис повернення не підтверджено. Повтор заблоковано.' ); }
	try {
		$result = self::reverse_issued_delivery_once( $delivery_id );
		if ( is_wp_error( $result ) ) { return $result; }
		wp_cache_delete( $delivery_id, 'post_meta' );
		if ( get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true ) !== '' ) { return new WP_Error( 'rework', 'Повернення не підтверджено журналом. Повтор заблоковано до звірки.' ); }
		foreach ( $targets as $item_id => $expected ) {
			$item = TKD_FO_DB::get_item( $item_id );
			if ( ! $item || round( (float) $item->on_hand, 3 ) !== round( $expected['on_hand'], 3 ) || round( (float) $item->reserved, 3 ) !== round( $expected['reserved'], 3 ) ) { return new WP_Error( 'rework', 'Залишки після повернення не підтверджено. Повтор заблоковано до звірки.' ); }
		}
		$done = $intent; $done['state'] = 'committed'; $done['completed_at'] = current_time( 'mysql' );
		if ( ! update_post_meta( $delivery_id, $key, wp_slash( $done ), $intent ) ) { return new WP_Error( 'rework', 'Склад повернуто, але завершення не підтверджено. Не повторюйте дію.' ); }
		wp_cache_delete( $delivery_id, 'post_meta' );
		return get_post_meta( $delivery_id, $key, true ) === $done ? true : new WP_Error( 'rework', 'Потрібна звірка завершення повернення.' );
	} catch ( Throwable $e ) { return new WP_Error( 'rework', 'Невизначений результат повернення. Повторне поповнення складу заблоковано до звірки.' ); }
}

private static function reverse_issued_delivery_once( $delivery_id ) {
	$historical = self::historical_stock_guard( $delivery_id ); if ( is_wp_error( $historical ) ) { return $historical; }
	$journal = get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true );
	if ( ! is_array( $journal ) || ! $journal ) {
		return new WP_Error( 'tkd_fo_delivery_legacy_issue', 'Для цієї старої видаткової немає журналу автоматичного списання. Склад не змінено; виконайте коригування вручну.' );
	}
	$order_id   = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_order_id', true ) );
	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$number     = trim( (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_number', true ) );
	$current_order_status  = sanitize_key( (string) get_post_meta( $order_id, '_tkd_status', true ) );
	$previous_order_status = sanitize_key( (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_previous_order_status', true ) );
	$target_order_status   = 'shipped' === $current_order_status && $previous_order_status ? $previous_order_status : $current_order_status;
	$restore_reservation   = in_array( $target_order_status, array( 'payment_pending', 'cod_pending', 'invoice_pending', 'prepayment_invoice_sent', 'partially_paid', 'balance_pending', 'paid', 'deferred_payment' ), true );
	if ( self::reconciliation_scope( $delivery_id, 'return_received' ) ) { $restore_reservation = false; }
	$processed  = array();

	foreach ( $journal as $entry ) {
		$item_id = absint( isset( $entry['item_id'] ) ? $entry['item_id'] : 0 );
		$qty     = TKD_FO_DB::decimal( isset( $entry['quantity'] ) ? $entry['quantity'] : 0, 3 );
		$restore = $restore_reservation ? TKD_FO_DB::decimal( isset( $entry['reserved_released'] ) ? $entry['reserved_released'] : 0, 3 ) : 0;
		$result  = TKD_FO_DB::change_stock(
			$item_id,
			array( 'on_hand' => $qty, 'reserved' => $restore ),
			array( 'type' => 'delivery_return', 'order_id' => $order_id, 'invoice_id' => $invoice_id, 'note' => 'Скасування видаткової № ' . $number . ': повернення на склад' )
		);
		if ( is_wp_error( $result ) ) {
			self::rollback_return_changes( $processed, $order_id, $invoice_id, $number );
			return $result;
		}
		$processed[] = array( 'item_id' => $item_id, 'sku' => isset( $entry['sku'] ) ? $entry['sku'] : '', 'quantity' => $qty, 'reserved_released' => $restore );
	}

	self::restore_order_reservation( $order_id, $processed );
	delete_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal' );
	delete_post_meta( $delivery_id, '_tkd_fo_delivery_stock_processed_at' );
	if ( 'shipped' === $current_order_status && $previous_order_status ) {
		update_post_meta( $order_id, '_tkd_status', $previous_order_status );
	}
	delete_post_meta( $delivery_id, '_tkd_fo_delivery_previous_order_status' );
	self::refresh_order_fulfillment( $order_id, $invoice_id );
	return true;
}

private static function rollback_stock_changes( $processed, $order_id, $invoice_id, $number ) {
	foreach ( array_reverse( $processed ) as $entry ) {
		TKD_FO_DB::change_stock(
			$entry['item_id'],
			array( 'on_hand' => $entry['quantity'], 'reserved' => $entry['reserved_released'] ),
			array( 'type' => 'delivery_rollback', 'order_id' => $order_id, 'invoice_id' => $invoice_id, 'note' => 'Відкат невдалого проведення видаткової № ' . $number )
		);
	}
}

private static function rollback_return_changes( $processed, $order_id, $invoice_id, $number ) {
	foreach ( array_reverse( $processed ) as $entry ) {
		TKD_FO_DB::change_stock(
			$entry['item_id'],
			array( 'on_hand' => -$entry['quantity'], 'reserved' => -$entry['reserved_released'] ),
			array( 'type' => 'delivery_rollback', 'order_id' => $order_id, 'invoice_id' => $invoice_id, 'note' => 'Відкат невдалого повернення видаткової № ' . $number )
		);
	}
}

private static function order_reservation_map( $order_id ) {
	$map      = array();
	$reserved = get_post_meta( $order_id, '_tkd_fo_reserved_items', true );
	foreach ( is_array( $reserved ) ? $reserved : array() as $line ) {
		$item_id = absint( isset( $line['item_id'] ) ? $line['item_id'] : 0 );
		if ( $item_id ) {
			$map[ $item_id ] = isset( $map[ $item_id ] ) ? $map[ $item_id ] : 0;
			$map[ $item_id ] = round( $map[ $item_id ] + (float) ( isset( $line['quantity'] ) ? $line['quantity'] : 0 ), 3 );
		}
	}
	return $map;
}

private static function reduce_order_reservation( $order_id, $shipped ) {
	$reserved = get_post_meta( $order_id, '_tkd_fo_reserved_items', true );
	$reserved = is_array( $reserved ) ? $reserved : array();
	$release  = array();
	foreach ( $shipped as $entry ) {
		$release[ (int) $entry['item_id'] ] = isset( $release[ (int) $entry['item_id'] ] ) ? $release[ (int) $entry['item_id'] ] + (float) $entry['reserved_released'] : (float) $entry['reserved_released'];
	}
	$remaining = array();
	foreach ( $reserved as $line ) {
		$item_id = absint( isset( $line['item_id'] ) ? $line['item_id'] : 0 );
		$qty     = TKD_FO_DB::decimal( isset( $line['quantity'] ) ? $line['quantity'] : 0, 3 );
		$take    = min( $qty, isset( $release[ $item_id ] ) ? $release[ $item_id ] : 0 );
		$qty     = round( $qty - $take, 3 );
		$release[ $item_id ] = round( ( isset( $release[ $item_id ] ) ? $release[ $item_id ] : 0 ) - $take, 3 );
		if ( $qty > 0 ) {
			$line['quantity'] = $qty;
			$remaining[] = $line;
		}
	}
	if ( $remaining ) {
		update_post_meta( $order_id, '_tkd_fo_reserved_items', $remaining );
	} else {
		delete_post_meta( $order_id, '_tkd_fo_reserved_items' );
	}
}

private static function restore_order_reservation( $order_id, $returned ) {
	$reserved = get_post_meta( $order_id, '_tkd_fo_reserved_items', true );
	$map      = array();
	foreach ( is_array( $reserved ) ? $reserved : array() as $line ) {
		$item_id = absint( isset( $line['item_id'] ) ? $line['item_id'] : 0 );
		if ( $item_id ) {
			$map[ $item_id ] = array( 'item_id' => $item_id, 'sku' => isset( $line['sku'] ) ? $line['sku'] : '', 'quantity' => (float) $line['quantity'] );
		}
	}
	foreach ( $returned as $entry ) {
		if ( $entry['reserved_released'] <= 0 ) {
			continue;
		}
		$item_id = (int) $entry['item_id'];
		if ( ! isset( $map[ $item_id ] ) ) {
			$map[ $item_id ] = array( 'item_id' => $item_id, 'sku' => $entry['sku'], 'quantity' => 0 );
		}
		$map[ $item_id ]['quantity'] = round( $map[ $item_id ]['quantity'] + (float) $entry['reserved_released'], 3 );
	}
	if ( $map ) {
		update_post_meta( $order_id, '_tkd_fo_reserved_items', array_values( $map ) );
	}
}

private static function delivery_items_for_display( $delivery_id ) {
	$items = get_post_meta( $delivery_id, '_tkd_fo_delivery_items', true );
	$items = is_array( $items ) ? $items : array();
	$status = (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_status', true );
	if ( in_array( $status, array( 'issued', 'cancelled' ), true ) ) {
		return array( 'items' => $items, 'error' => '' );
	}

	$invoice_id = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$invoice_items = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	$effective = $items;
	$seen = array();
	foreach ( $items as $key => $item ) {
		$index = isset( $item['source_index'] ) ? (int) $item['source_index'] : -1;
		if ( $index < 0 || (string) $index !== (string) $item['source_index'] || isset( $seen[ $index ] ) || ! is_array( $invoice_items ) || ! isset( $invoice_items[ $index ] ) || ! self::same_source_item( $item, $invoice_items[ $index ] ) ) {
			return array( 'items' => $items, 'error' => self::source_mismatch_message() );
		}
		$seen[ $index ] = true;
		$effective[ $key ]['unit_price'] = isset( $invoice_items[ $index ]['unit_price'] ) ? (float) $invoice_items[ $index ]['unit_price'] : 0;
	}
	return array( 'items' => $effective, 'error' => '' );
}

private static function same_source_item( $item, $source ) {
	if ( ! is_array( $item ) || ! is_array( $source ) || ! isset( $item['sku'], $item['name'], $item['unit'], $source['sku'], $source['name'], $source['unit'] ) ) {
		return false;
	}
	return (string) $item['sku'] === (string) $source['sku']
		&& (string) $item['unit'] === (string) $source['unit']
		&& ( '' !== (string) $item['sku'] || (string) $item['name'] === (string) $source['name'] );
}

private static function source_mismatch_message() {
	return 'Позиції пов’язаного рахунку змінено: артикул або порядок рядків не відповідає видатковій. Збереження та PDF чернетки заблоковано. Оновіть сторінку й перевірте позиції або скасуйте чернетку та створіть нову видаткову.';
}

private static function sanitize_items( $invoice_id, $delivery_id, $raw_items ) {
	$invoice_items = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	if ( ! is_array( $invoice_items ) ) {
		return array( 'items' => array(), 'error' => self::source_mismatch_message(), 'source_mismatch' => true );
	}
	$other = self::allocated_quantities( $invoice_id, $delivery_id );
	$items = array();
	$error = '';
	$seen = array();
	foreach ( is_array( $raw_items ) ? $raw_items : array() as $raw ) {
		$index = isset( $raw['source_index'] ) ? (int) $raw['source_index'] : -1;
		$qty   = TKD_FO_DB::decimal( isset( $raw['quantity'] ) ? $raw['quantity'] : 0, 3 );
		if ( $qty <= 0 ) {
			continue;
		}
		if ( $index < 0 || (string) $index !== (string) $raw['source_index'] || isset( $seen[ $index ] ) || ! isset( $invoice_items[ $index ] ) || ! self::same_source_item( $raw, $invoice_items[ $index ] ) ) {
			return array( 'items' => array(), 'error' => self::source_mismatch_message(), 'source_mismatch' => true );
		}
		$seen[ $index ] = true;
		$source    = $invoice_items[ $index ];
		$available = max( 0, (float) $source['quantity'] - ( isset( $other[ $index ] ) ? (float) $other[ $index ] : 0 ) );
		if ( $qty > $available + 0.0001 ) {
			$qty   = $available;
			$error = 'Кількість зменшено до доступної: частина товару вже включена в інші видаткові.';
		}
		if ( $qty <= 0 ) {
			continue;
		}
		$items[] = array(
			'source_index'   => $index,
			'sku'            => isset( $source['sku'] ) ? $source['sku'] : '',
			'name'           => isset( $source['name'] ) ? $source['name'] : '',
			'unit'           => isset( $source['unit'] ) ? $source['unit'] : 'шт',
			'quantity'       => $qty,
			'unit_price'     => isset( $source['unit_price'] ) ? (float) $source['unit_price'] : 0,
			'serial_numbers' => self::sanitize_serial_numbers( isset( $raw['serial_numbers'] ) ? $raw['serial_numbers'] : '' ),
		);
	}
	return array( 'items' => $items, 'error' => $error );
}

private static function sanitize_serial_numbers( $value ) {
	$value = sanitize_textarea_field( (string) $value );
	$value = str_replace( array( "\r\n", "\r" ), "\n", $value );
	$lines = preg_split( '/[\n,;]+/u', $value );
	$clean = array();
	foreach ( is_array( $lines ) ? $lines : array() as $line ) {
		$line = trim( $line );
		if ( '' !== $line && ! in_array( $line, $clean, true ) ) {
			$clean[] = $line;
		}
	}
	return implode( "\n", $clean );
}

public static function create_from_invoice() {
	if ( ! current_user_can( 'manage_tkd_felicity' ) ) {
		wp_die( 'Недостатньо прав.' );
	}
	$invoice_id = isset( $_GET['invoice_id'] ) ? absint( $_GET['invoice_id'] ) : 0;
	check_admin_referer( 'tkd_fo_create_delivery_' . $invoice_id );
	if ( ! $invoice_id || 'tkd_invoice' !== get_post_type( $invoice_id ) ) {
		wp_die( 'Рахунок не знайдено.' );
	}
	$invoice_items = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	$allocated     = self::allocated_quantities( $invoice_id );
	$items         = array();
	foreach ( is_array( $invoice_items ) ? $invoice_items : array() as $index => $source ) {
		$remaining = max( 0, (float) $source['quantity'] - ( isset( $allocated[ $index ] ) ? (float) $allocated[ $index ] : 0 ) );
		if ( $remaining <= 0 ) {
			continue;
		}
		$items[] = array(
			'source_index' => $index,
			'sku'          => isset( $source['sku'] ) ? $source['sku'] : '',
			'name'         => isset( $source['name'] ) ? $source['name'] : '',
			'unit'         => isset( $source['unit'] ) ? $source['unit'] : 'шт',
			'quantity'     => $remaining,
			'unit_price'   => isset( $source['unit_price'] ) ? (float) $source['unit_price'] : 0,
		);
	}
	if ( ! $items ) {
		TKD_FO_Inventory_Admin::set_notice( 'error', 'Усі позиції рахунку вже розподілені між видатковими накладними.' );
		wp_safe_redirect( get_edit_post_link( $invoice_id, '' ) );
		exit;
	}

	$date        = wp_date( 'Y-m-d' );
	$seller      = get_post_meta( $invoice_id, '_tkd_fo_seller_key', true );
	$number      = self::next_number( $seller, $date );
	$order_id    = absint( get_post_meta( $invoice_id, '_tkd_fo_order_id', true ) );
	$buyer_name  = get_post_meta( $invoice_id, '_tkd_fo_buyer_name', true );
	$receiver    = get_post_meta( $invoice_id, '_tkd_fo_receiver', true );
	$payer       = get_post_meta( $invoice_id, '_tkd_fo_payer', true );
	$application = get_post_meta( $invoice_id, '_tkd_fo_application', true );
	if ( ! $application && $order_id ) {
		$application = get_post_meta( $order_id, '_tkd_order_number', true );
	}

	$delivery_id = wp_insert_post( array( 'post_type' => 'tkd_delivery', 'post_status' => 'publish', 'post_title' => 'Видаткова накладна ' . $number ) );
	if ( is_wp_error( $delivery_id ) || ! $delivery_id ) {
		wp_die( 'Не вдалося створити видаткову накладну.' );
	}
	update_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', $invoice_id );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_order_id', $order_id );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_seller_key', $seller );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_number', $number );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_date', $date );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_place', 'м. Дніпро' );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_status', 'draft' );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_receiver', $receiver ? $receiver : $buyer_name );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_payer', $payer ? $payer : $buyer_name );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_contract', get_post_meta( $invoice_id, '_tkd_fo_contract', true ) );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_application', $application );
	update_post_meta( $delivery_id, '_tkd_fo_delivery_items', $items );
	TKD_FO_Inventory_Admin::set_notice( 'success', 'Створено окрему видаткову накладну. Перевірте фактичну кількість і дату.' );
	TKD_FO_Orders::claim_responsibility( $order_id, 'Створено видаткову № ' . $number );
	wp_safe_redirect( get_edit_post_link( $delivery_id, '' ) );
	exit;
}

private static function allocated_quantities( $invoice_id, $exclude_delivery_id = 0 ) {
	$allocated = array();
	if ( ! $invoice_id ) {
		return $allocated;
	}
	$deliveries = get_posts(
		array(
			'post_type'      => 'tkd_delivery',
			'post_status'    => 'any',
			'posts_per_page' => -1,
			'post__not_in'   => $exclude_delivery_id ? array( absint( $exclude_delivery_id ) ) : array(),
			'meta_key'       => '_tkd_fo_delivery_invoice_id',
			'meta_value'     => $invoice_id,
			'fields'         => 'ids',
		)
	);
	foreach ( $deliveries as $delivery_id ) {
		if ( 'cancelled' === get_post_meta( $delivery_id, '_tkd_fo_delivery_status', true ) ) {
			continue;
		}
		$items = get_post_meta( $delivery_id, '_tkd_fo_delivery_items', true );
		foreach ( is_array( $items ) ? $items : array() as $item ) {
			$index = isset( $item['source_index'] ) ? (int) $item['source_index'] : -1;
			if ( $index < 0 ) {
				continue;
			}
			$allocated[ $index ] = isset( $allocated[ $index ] ) ? $allocated[ $index ] + (float) $item['quantity'] : (float) $item['quantity'];
		}
	}
	return $allocated;
}

public static function issued_quantities_for_order( $order_id ) {
	$quantities = array();
	$deliveries = get_posts(
		array(
			'post_type'      => 'tkd_delivery',
			'post_status'    => 'any',
			'posts_per_page' => -1,
			'meta_key'       => '_tkd_fo_delivery_order_id',
			'meta_value'     => absint( $order_id ),
			'fields'         => 'ids',
		)
	);
	foreach ( $deliveries as $delivery_id ) {
		if ( 'cancelled' === (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_status', true ) ) {
			continue;
		}
		$journal = get_post_meta( $delivery_id, '_tkd_fo_delivery_stock_journal', true );
		foreach ( is_array( $journal ) ? $journal : array() as $entry ) {
			$sku = strtoupper( trim( (string) ( isset( $entry['sku'] ) ? $entry['sku'] : '' ) ) );
			if ( '' === $sku ) {
				continue;
			}
			$quantities[ $sku ] = isset( $quantities[ $sku ] ) ? $quantities[ $sku ] : 0;
			$quantities[ $sku ] = round( $quantities[ $sku ] + (float) ( isset( $entry['quantity'] ) ? $entry['quantity'] : 0 ), 3 );
		}
	}
	return $quantities;
}

private static function refresh_order_fulfillment( $order_id, $invoice_id ) {
	if ( ! $order_id || ! $invoice_id ) {
		return;
	}
	// Completion is determined against the whole order, not only the invoice
	// whose delivery note was just conducted. This matters when one order is
	// split into separate document packages for different legal sellers.
	if ( ( self::$reconciliation_scope['order'] ?? null ) === (int) $order_id ) {
		$invoice_items = self::$reconciliation_scope['order_items'];
	} else {
		$invoice_items = ( self::$handover_post_scope['order'] ?? null ) === (int) $order_id ? self::$handover_post_scope['order_items'] : ( class_exists( 'TKD_FO_Orders' ) ? TKD_FO_Orders::get_order_items( $order_id ) : get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true ) );
	}
	$delivered     = self::issued_quantities_for_order( $order_id );
	$total_qty     = 0;
	$delivered_qty = 0;
	foreach ( is_array( $invoice_items ) ? $invoice_items : array() as $line ) {
		$sku       = strtoupper( trim( (string) ( isset( $line['sku'] ) ? $line['sku'] : '' ) ) );
		$line_qty  = max( 0, (float) ( isset( $line['quantity'] ) ? $line['quantity'] : 0 ) );
		$used_qty  = min( $line_qty, isset( $delivered[ $sku ] ) ? (float) $delivered[ $sku ] : 0 );
		$total_qty += $line_qty;
		$delivered_qty += $used_qty;
		$delivered[ $sku ] = max( 0, ( isset( $delivered[ $sku ] ) ? (float) $delivered[ $sku ] : 0 ) - $used_qty );
	}
	$reserved = get_post_meta( $order_id, '_tkd_fo_reserved_items', true );
	if ( $total_qty > 0 && $delivered_qty + 0.0001 >= $total_qty ) {
		$cleanup = self::release_remaining_order_reservation( $order_id, $invoice_id );
		if ( is_wp_error( $cleanup ) ) {
			update_post_meta( $order_id, '_tkd_fo_stock_error', $cleanup->get_error_message() );
			update_post_meta( $order_id, '_tkd_fo_fulfillment_state', 'partial' );
			update_post_meta( $order_id, '_tkd_fo_stock_state', 'reserved' );
			return;
		}
		delete_post_meta( $order_id, '_tkd_fo_stock_error' );
		update_post_meta( $order_id, '_tkd_fo_fulfillment_state', 'complete' );
		update_post_meta( $order_id, '_tkd_status', 'shipped' );
		update_post_meta( $order_id, '_tkd_fo_stock_state', 'shipped' );
	} elseif ( $delivered_qty > 0 ) {
		update_post_meta( $order_id, '_tkd_fo_fulfillment_state', 'partial' );
		update_post_meta( $order_id, '_tkd_fo_stock_state', is_array( $reserved ) && $reserved ? 'reserved' : 'none' );
	} else {
		delete_post_meta( $order_id, '_tkd_fo_fulfillment_state' );
		update_post_meta( $order_id, '_tkd_fo_stock_state', is_array( $reserved ) && $reserved ? 'reserved' : 'none' );
		delete_post_meta( $order_id, '_tkd_fo_status_before_partial_delivery' );
	}
}

private static function release_remaining_order_reservation( $order_id, $invoice_id ) {
	$reserved = get_post_meta( $order_id, '_tkd_fo_reserved_items', true );
	$processed = array();
	foreach ( is_array( $reserved ) ? $reserved : array() as $line ) {
		$item_id = absint( isset( $line['item_id'] ) ? $line['item_id'] : 0 );
		$qty     = TKD_FO_DB::decimal( isset( $line['quantity'] ) ? $line['quantity'] : 0, 3 );
		$item    = $item_id ? TKD_FO_DB::get_item( $item_id ) : null;
		if ( $item_id && $qty > 0 && ( ! $item || (float) $item->reserved + 0.0001 < $qty ) ) {
			return new WP_Error( 'tkd_fo_delivery_cleanup_mismatch', 'Повне відвантаження проведено, але залишок резерву не збігається зі складом. Потрібна ручна перевірка.' );
		}
	}
	foreach ( is_array( $reserved ) ? $reserved : array() as $line ) {
		$item_id = absint( isset( $line['item_id'] ) ? $line['item_id'] : 0 );
		$qty     = TKD_FO_DB::decimal( isset( $line['quantity'] ) ? $line['quantity'] : 0, 3 );
		if ( ! $item_id || $qty <= 0 ) {
			continue;
		}
		$result = TKD_FO_DB::change_stock(
			$item_id,
			array( 'reserved' => -$qty ),
			array( 'type' => 'delivery_reserve_cleanup', 'order_id' => $order_id, 'invoice_id' => $invoice_id, 'note' => 'Закриття залишку резерву після повного відвантаження за видатковими' )
		);
		if ( is_wp_error( $result ) ) {
			foreach ( array_reverse( $processed ) as $done ) {
				TKD_FO_DB::change_stock( $done['item_id'], array( 'reserved' => $done['quantity'] ), array( 'type' => 'delivery_rollback', 'order_id' => $order_id, 'invoice_id' => $invoice_id, 'note' => 'Відкат закриття резерву після видаткових' ) );
			}
			return $result;
		}
		$processed[] = array( 'item_id' => $item_id, 'quantity' => $qty );
	}
	delete_post_meta( $order_id, '_tkd_fo_reserved_items' );
	return true;
}

private static function next_number( $seller, $date ) {
	$year = $date && strtotime( $date ) ? wp_date( 'Y', strtotime( $date ) ) : wp_date( 'Y' );
	$key  = 'tkd_fo_delivery_sequence_' . sanitize_key( $seller ? $seller : 'no_vat' ) . '_' . $year;
	$next = (int) get_option( $key, 0 ) + 1;
	do {
		$number = $year . '-' . str_pad( (string) $next, 4, '0', STR_PAD_LEFT );
		$next++;
	} while ( self::number_exists( $seller, $number, 0 ) );
	update_option( $key, $next - 1, false );
	return $number;
}

private static function number_exists( $seller, $number, $exclude_id ) {
	$query = new WP_Query(
		array(
			'post_type'      => 'tkd_delivery',
			'post_status'    => 'any',
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'post__not_in'   => $exclude_id ? array( absint( $exclude_id ) ) : array(),
			'meta_query'     => array(
				'relation' => 'AND',
				array( 'key' => '_tkd_fo_delivery_seller_key', 'value' => $seller ),
				array( 'key' => '_tkd_fo_delivery_number', 'value' => $number ),
			),
		)
	);
	return $query->have_posts();
}

public static function pdf_ready( $delivery_id ) {
	if ( get_post_meta( $delivery_id, '_tkd_fo_delivery_status', true ) !== 'issued' ) { return false; }
	$intent = get_post_meta( $delivery_id, self::HANDOVER_POST_META, true );
	// Older issued documents may predate the posting journal.
	return $intent === '' || ( is_array( $intent ) && ( $intent['state'] ?? '' ) === 'committed' );
}

public static function download_pdf() {
	if ( ! current_user_can( 'manage_tkd_felicity' ) ) {
		wp_die( 'Недостатньо прав.' );
	}
	$delivery_id = isset( $_GET['delivery_id'] ) ? absint( $_GET['delivery_id'] ) : 0;
	check_admin_referer( 'tkd_fo_download_delivery_pdf_' . $delivery_id );
	if ( ! $delivery_id || 'tkd_delivery' !== get_post_type( $delivery_id ) ) {
		wp_die( 'Видаткову накладну не знайдено.' );
	}
	wp_cache_delete( $delivery_id, 'post_meta' );
	if ( ! self::pdf_ready( $delivery_id ) ) {
		wp_die( 'PDF видаткової доступний після завершеного проведення.', '', array( 'response' => 409 ) );
	}
	$number = trim( (string) get_post_meta( $delivery_id, '_tkd_fo_delivery_number', true ) );
	$resolved = self::delivery_items_for_display( $delivery_id );
	if ( $resolved['error'] ) {
		wp_die( esc_html( $resolved['error'] ) );
	}
	$items = $resolved['items'];
	if ( ! $number || ! $items ) {
		wp_die( 'Видаткову без номера або номенклатури неможливо сформувати.' );
	}
	$without_stamp = isset( $_GET['without_stamp'] ) && '1' === sanitize_key( wp_unslash( $_GET['without_stamp'] ) );
	TKD_FO_Invoices::output_pdf(
		self::pdf_html( $delivery_id, $items, $without_stamp ),
		'Vydatkova-nakladna-' . sanitize_file_name( preg_replace( '/[^A-Za-z0-9._-]+/', '-', $number ) ) . '.pdf',
		'Видаткова накладна ' . preg_replace( '/[\\\\\/:*?"<>|]+/u', '-', $number ) . '.pdf',
		( $_GET['view'] ?? '' ) === '1'
	);
}

private static function calculate_totals( $delivery_id, $items ) {
	$items_subtotal = 0;
	foreach ( $items as $item ) {
		$items_subtotal += (float) $item['quantity'] * (float) $item['unit_price'];
	}
	$items_subtotal = round( $items_subtotal, 2 );
	$invoice_id     = absint( get_post_meta( $delivery_id, '_tkd_fo_delivery_invoice_id', true ) );
	$invoice_items_subtotal = (float) get_post_meta( $invoice_id, '_tkd_fo_invoice_items_subtotal', true );
	$invoice_discount = (float) get_post_meta( $invoice_id, '_tkd_fo_invoice_discount', true );
	$discount_rate = $invoice_items_subtotal > 0 ? min( 1, max( 0, $invoice_discount / $invoice_items_subtotal ) ) : 0;
	$discount = min( $items_subtotal, round( $items_subtotal * $discount_rate, 2 ) );
	$subtotal = round( $items_subtotal - $discount, 2 );
	$seller    = self::seller_key_for_delivery( $delivery_id );
	$vat_rate  = 'vat' === $seller && ! TKD_FO_Invoices::invoice_without_vat( $invoice_id ) ? max( 0, (float) get_option( 'tkd_fo_vat_rate', '20' ) ) : 0;
	$vat       = round( $subtotal * $vat_rate / 100, 2 );
	return array( 'items_subtotal' => $items_subtotal, 'discount_rate' => $discount_rate, 'discount' => $discount, 'subtotal' => $subtotal, 'vat_rate' => $vat_rate, 'vat' => $vat, 'total' => round( $subtotal + $vat, 2 ) );
}

