public static function download_invoice_pdf() {
	if ( ! current_user_can( 'manage_tkd_felicity' ) ) {
		wp_die( 'Недостатньо прав.' );
	}
	$invoice_id = isset( $_GET['invoice_id'] ) ? absint( $_GET['invoice_id'] ) : 0;
	check_admin_referer( 'tkd_fo_download_invoice_pdf_' . $invoice_id );
	if ( ! $invoice_id || 'tkd_invoice' !== get_post_type( $invoice_id ) ) {
		wp_die( 'Рахунок не знайдено.' );
	}
	$number = trim( (string) get_post_meta( $invoice_id, '_tkd_fo_invoice_number', true ) );
	$items  = get_post_meta( $invoice_id, '_tkd_fo_invoice_items', true );
	if ( ! $number || ! is_array( $items ) || ! $items ) {
		wp_die( 'Рахунок без номера або номенклатури неможливо сформувати.' );
	}
	$without_stamp = isset( $_GET['without_stamp'] ) && '1' === sanitize_key( wp_unslash( $_GET['without_stamp'] ) );
	if ( isset( $_GET['view'] ) && '1' === $_GET['view'] ) {
		self::render_invoice_mobile_view( $invoice_id, $number, $without_stamp );
		exit;
	}
	self::output_pdf(
		self::pdf_invoice_html( $invoice_id, $items, $without_stamp ),
		'Rakhunok-' . sanitize_file_name( preg_replace( '/[^A-Za-z0-9._-]+/', '-', $number ) ) . '.pdf',
		'Рахунок ' . preg_replace( '/[\\\\\/:*?"<>|]+/u', '-', $number ) . '.pdf'
	);
}

public static function output_pdf( $html, $filename, $filename_utf8, $inline = false ) {
	$autoload = TKD_FO_DIR . 'lib/dompdf/autoload.inc.php';
	if ( ! is_readable( $autoload ) ) {
		wp_die( 'Модуль створення PDF недоступний. Зверніться до адміністратора.' );
	}
	require_once $autoload;

	$uploads   = wp_upload_dir();
	$cache_dir = trailingslashit( $uploads['basedir'] ) . 'tkd-felicity-pdf-cache';
	if ( ! wp_mkdir_p( $cache_dir ) || ! is_writable( $cache_dir ) ) {
		$cache_dir = get_temp_dir();
	}

	$options = new \Dompdf\Options();
	$options->set( 'defaultFont', 'DejaVu Sans' );
	$options->set( 'isRemoteEnabled', false );
	$options->set( 'isHtml5ParserEnabled', true );
	$options->set( 'tempDir', $cache_dir );
	$options->set( 'fontCache', $cache_dir );
	$options->set( 'chroot', array( TKD_FO_DIR, $uploads['basedir'] ) );

	$dompdf = new \Dompdf\Dompdf( $options );
	$dompdf->loadHtml( $html, 'UTF-8' );
	$dompdf->setPaper( 'A4', 'portrait' );
	$dompdf->render();
	$pdf = $dompdf->output();

	while ( ob_get_level() ) {
		ob_end_clean();
	}
	nocache_headers();
	header( 'Content-Type: application/pdf' );
	header( 'Content-Disposition: ' . ( $inline ? 'inline' : 'attachment' ) . '; filename="' . $filename . '"; filename*=UTF-8\'\'' . rawurlencode( $filename_utf8 ) );
	header( 'Content-Length: ' . strlen( $pdf ) );
	echo $pdf; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
	exit;
}

