public static function document_signature_html( $signature, $stamp, $height = 27, $stamp_source = '' ) {
	if ( ! $signature && ! $stamp ) { return ''; }
	$height = max( 18, min( 27, (int) $height ) );
	$signature_width = round( $height * 1.4, 1 );
	$mark_height = $stamp ? 40 : $height;
	$signature_top = $stamp ? round( ( 40 - $height ) / 2 + 1, 1 ) : 1;
	$stamp_style = 'left:20mm;top:0;width:40mm;height:auto;max-height:40mm;';
	// Owner-approved processed stamp includes its signature. Calibrate the
	// visible ring (about 1076 x 1062 px on a 1254 px canvas) to 40 mm.
	if ( false !== strpos( (string) ( $stamp_source ?: $stamp ), 'rashchupkina-stamp-signature-20261013' ) ) {
		$stamp_style = 'left:17.077mm;top:-3.507mm;width:46.617mm;height:47.232mm;';
	}
	// This existing PNG has transparent padding. Calibrate the visible outer
	// ring (1105 x 1094 px on a 1254 px canvas), not the whole image, to 40 mm.
	if ( false !== strpos( (string) ( $stamp_source ?: $stamp ), 'pml-main-stamp-20261009.png' ) ) {
		$stamp_style = 'left:17.321mm;top:-3.108mm;width:45.394mm;height:45.850mm;';
	}
	// This owner's combined signature/seal has a 916 px ring on a 1320 x
	// 975 px canvas. Print the ring at 40 mm without cropping the signature.
	if ( $stamp && false !== strpos( (string) ( $stamp_source ?: $stamp ), 'mykheda-stamp-signature-20261109' ) ) {
		$stamp_style = 'left:2mm;top:0;width:57.642mm;height:42.576mm;';
		$mark_height = 43;
	}
	return '<div class="tkd-document-sign-mark" style="position:relative;width:62mm;height:' . $mark_height . 'mm;margin:0 auto;page-break-inside:avoid">'
		. ( $stamp ? '<img class="tkd-document-stamp" src="' . esc_attr( $stamp ) . '" alt="Печатка" style="position:absolute;' . $stamp_style . 'z-index:1">' : '' )
		. ( $signature ? '<img class="tkd-document-signature" src="' . esc_attr( $signature ) . '" alt="Підпис" style="position:absolute;left:1mm;top:' . $signature_top . 'mm;width:' . $signature_width . 'mm;height:auto;max-height:' . ( $height - 1 ) . 'mm;z-index:2">' : '' )
		. '</div>';
}

public static function copy_payment_data( $id ) {
    $post = get_post( $id );
    if ( ! $post || 'tkd_invoice' !== $post->post_type || in_array( $post->post_status, array( 'trash', 'auto-draft' ), true )
        || in_array( get_post_meta( $id, '_tkd_fo_invoice_status', true ), array( 'cancelled', 'archived' ), true ) ) { return array(); }
    $seller = self::invoice_seller_profile( $id );
    $number = (string) get_post_meta( $id, '_tkd_fo_invoice_number', true );
    $date = (string) get_post_meta( $id, '_tkd_fo_invoice_date', true );
    $date_text = $date ? date( 'd.m.Y', strtotime( $date ) ) : mysql2date( 'd.m.Y', $post->post_date, false );
    $total = (float) get_post_meta( $id, '_tkd_fo_invoice_total', true );
    if ( ! self::bank_qr_payload( $seller, $number, $date_text, $total ) ) { return array(); }
    $due = $total; $order = absint( get_post_meta( $id, '_tkd_fo_order_id', true ) );
    if ( $order && is_callable( array( 'TKD_FO_Payments', 'paid_total' ) ) ) {
        $paid = (float) TKD_FO_Payments::paid_total( $order );
        $ids = get_posts( array( 'post_type' => 'tkd_invoice', 'post_status' => 'any', 'posts_per_page' => -1, 'fields' => 'ids', 'meta_key' => '_tkd_fo_order_id', 'meta_value' => $order ) );
        $ids = array_values( array_filter( $ids, static function( $x ) { return ! in_array( get_post_meta( $x, '_tkd_fo_invoice_status', true ), array( 'cancelled', 'archived' ), true ); } ) );
        if ( $paid > 0 && count( $ids ) === 1 ) { $due = max( 0, $total - $paid ); }
        elseif ( $paid > 0 ) { $due = null; }
    }
    return array( 'IBAN' => strtoupper( preg_replace( '/\s+/', '', $seller['iban'] ) ),
        'ІПН / ЄДРПОУ' => (string) $seller['tax_id'], 'Отримувач' => (string) $seller['recipient_name'],
        'Призначення платежу' => self::bank_payment_purpose( $number, $date_text ),
        'Сума до сплати, грн' => null === $due ? 'Уточніть у менеджера: є оплати за кількома рахунками' : number_format( $due, 2, '.', '' ) );
}

public static function payment_copy_text( $id ) {
    $data = self::copy_payment_data( $id );
    if ( ! $data ) { return ''; }
    $total_cents = (int) round( (float) get_post_meta( $id, '_tkd_fo_invoice_total', true ) * 100 );
    $reserve_cents = intdiv( $total_cents + 2, 5 );
    return self::payment_text_from_data( $data ) . "\n\nДля резерву під поставку клієнт сплачує 20% від суми рахунку — "
        . number_format( $reserve_cents / 100, 2, ',', ' ' ) . ' грн.';
}

private static function payment_text_from_data( $data ) {
    $parts = array();
    foreach ( $data as $label => $value ) { $parts[] = $label . ":\n" . $value; }
    return implode( "\n\n", $parts );
}

