private static function bank_qr_payload( $seller, $number, $date_text, $total ) {
	$iban = strtoupper( preg_replace( '/\s+/u', '', (string) ( $seller['iban'] ?? '' ) ) );
	$name = trim( (string) ( $seller['recipient_name'] ?? '' ) );
	$tax  = trim( (string) ( $seller['tax_id'] ?? '' ) );
	$total = round( (float) $total, 2 );
	if ( ! preg_match( '/^UA[0-9]{27}$/D', $iban ) || ! preg_match( '/^(?:[0-9]{8}|[0-9]{10})$/D', $tax ) || ! is_finite( $total ) || $total <= 0 || $total > 999999999.99 || ! trim( (string) $number ) || ! trim( (string) $date_text ) ) { return ''; }
	// ISO 13616/7064 checksum, without requiring a big integer extension.
	$digits = substr( $iban, 4 ) . '3010' . substr( $iban, 2, 2 ); $remainder = 0;
	foreach ( str_split( $digits ) as $digit ) { $remainder = ( $remainder * 10 + (int) $digit ) % 97; }
	if ( 1 !== $remainder ) { return ''; }
	$purpose = self::bank_payment_purpose( $number, $date_text );
	foreach ( array( $name => 140, $purpose => 420 ) as $value => $limit ) {
		if ( '' === $value || ! preg_match( '//u', $value ) || preg_match( '/[\x00-\x1F\x7F\x{0098}\x{00A0}]/u', $value ) || preg_match_all( '/./us', $value, $unused ) > $limit ) { return ''; }
	}
	$amount = number_format( $total, 2, '.', '' );
	if ( substr( $amount, -3 ) === '.00' ) { $amount = substr( $amount, 0, -3 ); }
	$data = implode( "\n", array( 'BCD', '002', '1', 'UCT', '', $name, $iban, 'UAH' . $amount, $tax, '', '', $purpose, '' ) ) . "\n";
	$encoded = rtrim( strtr( base64_encode( $data ), '+/', '-_' ), '=' );
	// Never truncate payment details to fit a QR code.
	return strlen( $encoded ) <= 475 ? 'https://bank.gov.ua/qr/' . $encoded : '';
}

private static function bank_payment_purpose( $number, $date_text ) {
	return 'Оплата за товар згідно рахунку №' . $number . ' від ' . $date_text . ' р.';
}

private static function bank_qr_image( $payload ) {
	if ( ! $payload ) { return ''; }
	static $cache = array();
	if ( isset( $cache[ $payload ] ) ) { return $cache[ $payload ]; }
	// NBU physical QR versions 10–17. Prefer Q correction, use M if needed.
	$qr = null;
	foreach ( array( TKD_IBAN_QR_ERROR_CORRECT_LEVEL_Q, TKD_IBAN_QR_ERROR_CORRECT_LEVEL_M ) as $level ) {
		for ( $version = 10; $version <= 17; $version++ ) {
			$capacity = 0;
			foreach ( TKD_IBAN_QRRSBlock::getRSBlocks( $version, $level ) as $block ) { $capacity += $block->dataCount; }
			if ( 4 + 16 + strlen( $payload ) * 8 > $capacity * 8 ) { continue; }
			$qr = new TKD_IBAN_QRCode(); $qr->setTypeNumber( $version ); $qr->setErrorCorrectLevel( $level );
			$qr->addData( $payload, TKD_IBAN_QR_MODE_8BIT_BYTE ); $qr->make(); break 2;
		}
	}
	if ( ! $qr ) { return ''; }
	$n = $qr->getModuleCount(); $side = $n + 8; $path = '';
	for ( $y = 0; $y < $n; $y++ ) {
		for ( $x = 0; $x < $n; $x++ ) {
			if ( $qr->isDark( $y, $x ) ) { $path .= 'M' . ( $x + 4 ) . ',' . ( $y + 4 ) . 'h1v1h-1z'; }
		}
	}
	$diameter = $version === 10 ? 17 : ( $version <= 12 ? 19 : ( $version === 13 ? 21 : ( $version <= 15 ? 23 : 25 ) ) );
	$center = $side / 2;
	// The official hryvnia sign is drawn as a path; no font or image downloads.
	$glyph = 'M348 673Q352 680 374 702Q448 776 576 820H117V943H1031Q1043 951 1056 960Q1115 1003 1115 1110Q1115 1228 1025.5 1292.0Q936 1356 771 1356Q676 1356 574.0 1329.0Q472 1302 357 1247V1444Q471 1482 580.0 1501.0Q689 1520 794 1520Q1039 1520 1178.5 1406.0Q1318 1292 1318 1094Q1318 1009 1293 943H1468V820H1209Q1106 728 890 686L823 673H1468V550H527Q478 491 478 397Q478 271 572.0 203.0Q666 135 839 135Q953 135 1071.0 170.0Q1189 205 1312 274V66Q1184 19 1064.5 -5.0Q945 -29 839 -29Q558 -29 412.5 83.0Q267 195 267 412Q267 487 285 550H117V673Z';
	$scale = ( $diameter - 4 ) / 2055.3836624825058;
	$transform = 'translate(' . $center . ' ' . $center . ') scale(' . $scale . ' ' . -$scale . ') translate(-792.5 -745.5)';
	$svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' . $side . '" height="' . $side . '" viewBox="0 0 ' . $side . ' ' . $side . '"><rect width="' . $side . '" height="' . $side . '" fill="white"/><path fill="black" d="' . $path . '"/><circle cx="' . $center . '" cy="' . $center . '" r="' . ( $diameter / 2 ) . '" fill="white"/><path fill="black" transform="' . $transform . '" d="' . $glyph . '"/></svg>';
	return $cache[ $payload ] = 'data:image/svg+xml;base64,' . base64_encode( $svg );
}

