public static function local_image_data_uri( $url ) {
	if ( ! $url ) {
		return '';
	}
	$uploads = wp_get_upload_dir();
	$roots   = array(
		array(
			'url' => trailingslashit( $uploads['baseurl'] ),
			'dir' => trailingslashit( wp_normalize_path( $uploads['basedir'] ) ),
		),
		array(
			'url' => trailingslashit( TKD_FO_URL ),
			'dir' => trailingslashit( wp_normalize_path( TKD_FO_DIR ) ),
		),
	);
	$path = '';
	foreach ( $roots as $root ) {
		if ( 0 !== strpos( $url, $root['url'] ) ) {
			continue;
		}
		$relative  = ltrim( substr( $url, strlen( $root['url'] ) ), '/' );
		$candidate = wp_normalize_path( $root['dir'] . $relative );
		$real_root = realpath( $root['dir'] );
		$real_path = realpath( $candidate );
		if ( false !== $real_root && false !== $real_path ) {
			$real_root = trailingslashit( wp_normalize_path( $real_root ) );
			$real_path = wp_normalize_path( $real_path );
			if ( 0 === strpos( $real_path, $real_root ) && is_readable( $real_path ) ) {
				$path = $real_path;
			}
		}
		break;
	}
	if ( ! $path ) {
		return '';
	}
	$type = wp_check_filetype( $path );
	$mime = isset( $type['type'] ) ? $type['type'] : '';
	if ( ! in_array( $mime, array( 'image/jpeg', 'image/png', 'image/gif', 'image/svg+xml' ), true ) ) {
		return '';
	}
	$data = file_get_contents( $path );
	return false === $data ? '' : 'data:' . $mime . ';base64,' . base64_encode( $data );
}

private static function normalize_seller_key( $seller_key ) {
	$seller_key = sanitize_key( (string) $seller_key );
	$profiles   = TKD_FO_DB::seller_profiles();
	return isset( $profiles[ $seller_key ] ) ? $seller_key : 'no_vat';
}

