private static function buyer_value( $invoice_id, $key ) {
	$value = trim( (string) get_post_meta( $invoice_id, '_tkd_fo_' . $key, true ) );
	if ( '' !== $value ) {
		return $value;
	}
	$order_fields = array(
		'buyer_name'  => '_tkd_customer_name',
		'buyer_phone' => '_tkd_customer_phone',
		'buyer_email' => '_tkd_customer_email',
		'application' => '_tkd_order_number',
	);
	if ( ! isset( $order_fields[ $key ] ) ) {
		return '';
	}
	$order_id = self::linked_order_id( $invoice_id );
	return $order_id ? trim( (string) get_post_meta( $order_id, $order_fields[ $key ], true ) ) : '';
}

private static function invoice_seller_profile( $invoice_id ) {
	$seller_key = self::normalize_seller_key( get_post_meta( $invoice_id, '_tkd_fo_seller_key', true ) );
	$profiles   = TKD_FO_DB::seller_profiles();
	$seller     = $profiles[ $seller_key ];
	$seller['key'] = $seller_key;
	$seller['recipient_name'] = $seller['legal_name'];
	if ( 'fop_rv' === $seller_key ) {
		$bank = get_post_meta( $invoice_id, '_tkd_fo_rv_bank_snapshot', true );
		if ( is_array( $bank ) && ! empty( $bank['iban'] ) ) {
			foreach ( array( 'iban', 'bank_name', 'mfo' ) as $field ) {
				if ( isset( $bank[ $field ] ) ) { $seller[ $field ] = $bank[ $field ]; }
			}
		}
	}

	if ( in_array( $seller_key, array( 'no_vat', 'fop_md' ), true ) ) {
		$banks    = self::bank_choices_for_seller( $seller_key );
		$bank_key = self::normalize_bank_key( $seller_key, get_post_meta( $invoice_id, '_tkd_fo_bank_key', true ) );
		$bank     = $banks[ $bank_key ];
		foreach ( array( 'recipient_name', 'tax_id', 'bank_name', 'iban', 'mfo' ) as $field ) {
			$seller[ $field ] = isset( $bank[ $field ] ) ? $bank[ $field ] : '';
		}
	}

	if ( get_post_meta( self::linked_order_id( $invoice_id ), '_tkd_ti_mono_v1', true ) ) {
		$seller['iban'] = ''; $seller['mfo'] = ''; $seller['bank_name'] = 'Покупка частинами monobank — оплата за договором банку';
	}
	return $seller;
}

public static function money( $value ) {
	return self::number( $value ) . ' грн';
}

public static function number( $value ) {
	return number_format( (float) $value, 2, ',', ' ' );
}

public static function quantity( $value ) {
	$value = (float) $value;
	return floor( $value ) === $value ? (string) (int) $value : number_format( $value, 3, ',', ' ' );
}

public static function amount_words( $amount ) {
	$amount = round( (float) $amount, 2 );
	$whole  = (int) floor( $amount );
	$kop    = (int) round( ( $amount - $whole ) * 100 );
	$words  = self::integer_words( $whole );
	$words .= ' ' . self::plural( $whole, 'гривня', 'гривні', 'гривень' );
	$words .= ' ' . str_pad( (string) $kop, 2, '0', STR_PAD_LEFT ) . ' ' . self::plural( $kop, 'копійка', 'копійки', 'копійок' );
	if ( function_exists( 'mb_strtoupper' ) ) {
		$words = mb_strtoupper( mb_substr( $words, 0, 1, 'UTF-8' ), 'UTF-8' ) . mb_substr( $words, 1, null, 'UTF-8' );
	}
	return $words;
}

private static function integer_words( $number ) {
	if ( 0 === (int) $number ) {
		return 'нуль';
	}
	$ones_m = array( '', 'один', 'два', 'три', 'чотири', 'п’ять', 'шість', 'сім', 'вісім', 'дев’ять' );
	$ones_f = array( '', 'одна', 'дві', 'три', 'чотири', 'п’ять', 'шість', 'сім', 'вісім', 'дев’ять' );
	$teens  = array( 10 => 'десять', 11 => 'одинадцять', 12 => 'дванадцять', 13 => 'тринадцять', 14 => 'чотирнадцять', 15 => 'п’ятнадцять', 16 => 'шістнадцять', 17 => 'сімнадцять', 18 => 'вісімнадцять', 19 => 'дев’ятнадцять' );
	$tens   = array( 2 => 'двадцять', 3 => 'тридцять', 4 => 'сорок', 5 => 'п’ятдесят', 6 => 'шістдесят', 7 => 'сімдесят', 8 => 'вісімдесят', 9 => 'дев’яносто' );
	$hund   = array( 1 => 'сто', 2 => 'двісті', 3 => 'триста', 4 => 'чотириста', 5 => 'п’ятсот', 6 => 'шістсот', 7 => 'сімсот', 8 => 'вісімсот', 9 => 'дев’ятсот' );
	$scales = array( 1 => array( 'тисяча', 'тисячі', 'тисяч', true ), 2 => array( 'мільйон', 'мільйони', 'мільйонів', false ), 3 => array( 'мільярд', 'мільярди', 'мільярдів', false ) );
	$parts  = array();
	$group  = 0;
	while ( $number > 0 ) {
		$triad = $number % 1000;
		if ( $triad ) {
			$chunk = array();
			$h = (int) floor( $triad / 100 );
			$r = $triad % 100;
			if ( $h ) { $chunk[] = $hund[ $h ]; }
			if ( $r >= 10 && $r <= 19 ) {
				$chunk[] = $teens[ $r ];
			} else {
				$t = (int) floor( $r / 10 );
				$o = $r % 10;
				if ( $t ) { $chunk[] = $tens[ $t ]; }
				if ( $o ) {
					$female  = isset( $scales[ $group ] ) && $scales[ $group ][3];
					$chunk[] = $female ? $ones_f[ $o ] : $ones_m[ $o ];
				}
			}
			if ( $group && isset( $scales[ $group ] ) ) {
				$chunk[] = self::plural( $triad, $scales[ $group ][0], $scales[ $group ][1], $scales[ $group ][2] );
			}
			array_unshift( $parts, implode( ' ', $chunk ) );
		}
		$number = (int) floor( $number / 1000 );
		$group++;
	}
	return implode( ' ', $parts );
}

private static function plural( $number, $one, $few, $many ) {
	$number = abs( (int) $number ) % 100;
	$last   = $number % 10;
	if ( $number > 10 && $number < 20 ) { return $many; }
	if ( 1 === $last ) { return $one; }
	if ( $last >= 2 && $last <= 4 ) { return $few; }
	return $many;
}
